       error: (err) => {
         this.error.set(err.error?.error || 'Erro ao confirmar pagamento');
         this.loading.set(false);
       },
     });
   }

   copyPix() {
     navigator.clipboard?.writeText(this.pix());
     this.success.set('Código Pix copiado!');
   }

   isMock() {
     return this.provider() === 'mock' || this.provider() === '';
   }

