   const channel = await sendVerificationMessage(user, code, token, 'ACCOUNT_ACTIVATION');

   console.log(`[AUTH] Clínica criada: ${tenant.name} (${tenant.slug}) | admin ${user.email} | trial 14d`);

   res.status(201).json({
