export type PixKeyType = 'CPF' | 'CNPJ' | 'EMAIL' | 'PHONE' | 'RANDOM';

// Normaliza a chave conforme o tipo — CPF/CNPJ/PHONE perdem pontuação;
// EMAIL e RANDOM preservam a chave exata como registrada no banco
export function normalizePixKey(key: string, keyType?: string): string {
  const t = (keyType || '').toUpperCase();
  if (t === 'EMAIL') return key.trim().toLowerCase();
  if (t === 'RANDOM') return key.trim();
  return key.replace(/[\s.-]/g, '');
}

