def crc_ccitt_false(data, init=0xFFFF):
    crc = init
    for ch in data:
        crc ^= ord(ch) << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc

def crc_xmodem(data):
    return crc_ccitt_false(data, 0x0000)

def crc_x25(data):
    crc = 0xFFFF
    for ch in data:
        crc ^= ord(ch)
        for _ in range(8):
            crc = (crc >> 1) ^ 0x8408 if crc & 1 else crc >> 1
    return crc ^ 0xFFFF

print("CCITT-FALSE(init FFFF):", format(crc_ccitt_false(payload), '04X'))
print("XMODEM      (init 0000):", format(crc_xmodem(payload), '04X'))
print("X25         (reflected):", format(crc_x25(payload), '04X'))
print("esperado: 1D3D")
